<script setup>
import{computed,onMounted,ref}from'vue';import{useRoute}from'vue-router';import{api}from'../services/api'
const route=useRoute(),detail=ref(null),page=ref(1),image=ref(''),status=ref(''),note=ref('');const unit=computed(()=>detail.value?.unit);const first=computed(()=>Number(detail.value?.pages?.[0]||1));const last=computed(()=>Number(detail.value?.pages?.[1]||1));
async function load(){detail.value=await api.unitDetail(route.params.unit);page.value=first.value;await render()}async function render(){try{image.value=(await api.unitRender(route.params.unit,page.value)).url;status.value='Página lista para auditoría.'}catch(e){status.value=e.message}}async function decide(state){try{status.value=(await api.pageDecision({unit_id:route.params.unit,page:page.value,status:state})).message;detail.value.decisions={...detail.value.decisions,[String(page.value)]:{status:state}}}catch(e){status.value=e.message}}async function approve(){try{status.value=(await api.approveUnit(route.params.unit)).message}catch(e){status.value=e.message}}async function adjust(){if(!note.value.trim())return;try{status.value=(await api.requestAdjustment({unit_id:route.params.unit,page:page.value,note:note.value})).message;note.value=''}catch(e){status.value=e.message}}onMounted(load)
</script>
<template><section class="hero"><span class="eyebrow">AUDITORÍA DE UNIDAD</span><h2>{{unit?.name||route.params.unit}}</h2><p>Comparación del PDF y la propuesta DTBook para una unidad nueva del proyecto.</p></section><section class="audit-toolbar"><button class="secondary" :disabled="page<=first" @click="page--;render()">← Anterior</button><strong>Página {{page}} de {{last}}</strong><button class="secondary" :disabled="page>=last" @click="page++;render()">Siguiente →</button><button class="secondary" @click="decide('correction')">Marcar corrección</button><button @click="decide('approved')">Aprobar página</button><button @click="approve">Aprobar unidad</button><span>{{status}}</span></section><section class="audit-grid"><article class="audit-panel"><header><strong>PDF</strong></header><img :src="image" alt="Página del PDF"/></article><article class="audit-panel"><header><strong>DTBook propuesto</strong></header><pre>{{detail?.proposal||'Aún no hay propuesta.'}}</pre></article><article class="audit-panel"><header><strong>Imágenes</strong><span>{{detail?.assets?.filter(x=>Number(x.page)===page).length||0}}</span></header><div class="image-row"><img v-for="asset in detail?.assets?.filter(x=>Number(x.page)===page)" :src="asset.url" :alt="asset.file"/></div></article></section><section class="correction-card"><h3>Solicitar corrección</h3><textarea v-model="note" placeholder="Describe el ajuste de esta página…"></textarea><button @click="adjust">Enviar solicitud</button></section></template>
